FOR UPDATE

SELECT

FROM memory_versions

    workspace_uuid = #{params.WorkspaceUUID}
    AND memory_store_external_id = #{params.MemoryStoreExternalID}

        AND memory_external_id = #{params.MemoryExternalID}


        AND operation = #{params.Operation}


        AND created_by_api_key_external_id = #{params.APIKeyExternalID}


        AND created_by_session_id = #{params.SessionID}


        AND created_at >= #{params.CreatedAtGTE}


        AND created_at <= #{params.CreatedAtLTE}


        AND (
            created_at < #{params.CursorCreatedAt}
            OR (created_at = #{params.CursorCreatedAt} AND uuid < #{params.CursorUUID})
        )


ORDER BY created_at DESC, uuid DESC
LIMIT #{params.Limit}

